// prettier-ignore
export const calculateColSpan = ({
  columns,
  isExpandable,
  isDraggable,
  isSelectable
}) => {
  let totalColSpans = columns.length;
  if (isExpandable) {
    totalColSpans += 1;
  }
  if (isDraggable) {
    totalColSpans += 1;
  }
  if (isSelectable) {
    totalColSpans += 1;
  }
  return totalColSpans;
};